//______________________________________________________________________________
// Build a symmetric quadrature rule on the unit reference triangle
//
//     T_ref = { (xi, eta) : xi >= 0, eta >= 0, xi + eta <= 1 }
//
// For each quadrature point k the routine writes
//
//     zeta[k][0] = xi_k
//     zeta[k][1] = eta_k
//
// The rule integrates polynomials of total degree `degree` exactly. The number
// of points n is selected from a Dunavant-style table built into this file
// and depends on `degree` (e.g. 1->1, 2->3, 3->6, 4->6, 5->7, ...).
//
// PARAMETERS
//   degree   [in ]  Total polynomial degree to integrate exactly.
//                   Supported range: 1 <= degree <= 30. Out-of-range values
//                   trigger print_error_message() and abort.
//   n        [out]  Number of quadrature points selected for this degree.
//   zeta     [out]  Newly allocated n x 2 matrix of quadrature point coordinates.
//   weights  [out]  Newly allocated array of length n. Weights are scaled so
//                   that sum_k weights[k] = 1/2, i.e. the area of T_ref.
//                   Therefore for a constant integrand f = c the rule yields
//                   c * Area(T_ref) = c/2 as expected.
//
// MEMORY
//   `zeta` and `weights` are allocated inside the function. Free them with
//   deallocate(zeta, n, 2) and deallocate(weights, n).
//
// USAGE EXAMPLE
//     int n;
//     double **xi = nullptr;
//     double  *w  = nullptr;
//     get_triangle_quadrature_points(5, n, xi, w);
//     // integrate f over a physical triangle with Jacobian determinant detJ:
//     //   I = sum_k w[k] * f(xi[k][0], xi[k][1]) * detJ
//     deallocate(xi, n, 2);
//     deallocate(w,  n);
